const overlay=document.querySelector('#overlay'),hud=document.querySelector('#hud');
const $=s=>document.querySelector(s),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const formatTime=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
const art=id=>{const custom={might:0,haste:1,vitality:2,magnet:3,wand:4};if(custom[id]!==undefined)return `<span class="item-art ui-item-icon" aria-hidden="true" style="background-position:${custom[id]%3*50}% ${Math.floor(custom[id]/3)*100}%"></span>`;const i=ITEMS[id];return i?.crownIcon!==undefined?`<span class="item-art crown-icon" style="background-position:${i.crownIcon*100}% 0"></span>`:i?.arsenalIcon!==undefined?`<span class="item-art arsenal-icon" style="background-position:${i.arsenalIcon%3*50}% ${Math.floor(i.arsenalIcon/3)*100}%"></span>`:i?.rangerIcon!==undefined?`<span class="item-art ranger-icon" style="background-position:${i.rangerIcon*100/3}% 100%"></span>`:i?.rewardIcon!==undefined?`<span class="item-art reward-icon" style="background-position:${(i.rewardIcon%4)*100/3}% ${Math.floor(i.rewardIcon/4)*100}%"></span>`:i?.witchIcon!==undefined?`<span class="item-art witch-icon" style="background-position:${i.witchIcon*100/3}% 100%"></span>`:i?.icon!==undefined?`<span class="item-art" style="background-position:${(i.icon%4)*100/3}% ${Math.floor(i.icon/4)*100}%"></span>`:`<span class="glyph">${i?.glyph||'◆'}</span>`};
const button=(text,id,cls='secondary')=>`<button class="${cls}" id="${id}">${text}</button>`;
