 this.floor=this.add.tileSprite(this.world.w/2,this.world.h/2,800,800,'ground').setDepth(-100);this.floor.setTileScale(.35,.35);this.obstacles=[];this.decor=[];this.makeWorld();this.beacons=this.add.graphics().setDepth(40000);this.effects=this.add.graphics().setDepth(40001);this.joy=this.add.graphics().setScrollFactor(0).setDepth(50000);this.health=this.add.graphics().setDepth(40002);this.guardMarker=this.add.graphics();this.player=this.add.sprite(1800,1350,'characters','cell0').setDisplaySize(72,72).setOrigin(.5,.94);this.shadow=this.add.ellipse(1800,1350,30,10,0x000000,.32).setDepth(1349);this.keys=this.input.keyboard.addKeys('W,A,S,D,UP,DOWN,LEFT,RIGHT,ESC,ONE,TWO,THREE,FOUR');this.input.addPointer(2);this.joystick=null;this.input.on('pointerdown',p=>{if(this.mode==='playing'&&!this.joystick)this.joystick={id:p.id,x:p.x,y:p.y,dx:0,dy:0};});this.input.on('pointermove',p=>{const j=this.joystick;if(j&&j.id===p.id){let dx=p.x-j.x,dy=p.y-j.y;const d=Math.hypot(dx,dy),r=48;j.dx=dx/Math.max(r,d);j.dy=dy/Math.max(r,d);}});this.input.on('pointerup',p=>{if(this.joystick?.id===p.id)this.releaseInput();});this.input.on('gameout',()=>this.releaseInput());this.input.keyboard.on('keydown-M',()=>{if(this.mode==='playing')this.openMap();else if(this.mode==='map')$('#map-close')?.click();});this.input.keyboard.on('keydown-ESC',()=>{if(this.mode==='playing')pause();else if(this.mode==='paused')$('#resume')?.click();else if(this.mode==='map')$('#map-close')?.click();else if(this.mode==='settings')menu();else if(['reference','achievements'].includes(this.mode))this.referenceBack?.();});['ONE','TWO','THREE','FOUR'].forEach((k,i)=>this.keys[k].on('down',()=>{if(this.mode==='levelup')overlay.querySelectorAll('[data-choice]')[i]?.click();}));this.scale.on('resize',()=>this.resize());this.resize();this.camera.startFollow(this.player,true,1,1);this.camera.setBounds(0,0,this.world.w,this.world.h);this.enemies=[];this.gems=[];this.chests=[];this.bolts=[];this.pools=[];this.floaters=[];this.e