 reportAchievements(){const completed=account?.achievements?.completed||[];const fresh=ACHIEVEMENTS.filter(a=>completed.includes(a.id)&&!this.knownAchievements?.has(a.id));for(const a of fresh)this.knownAchievements.add(a.id);if(fresh.length)toast(fresh.map(a=>a.id==='last_bell'?'Keep Key unlocked! +500 coins saved.':a.id==='out_of_depths'?'First floor unlocked! +750 coins saved.':a.id==='crown_broken'?'The Crownless and Crownshards unlocked!':a.id==='ranger'?'Ranger and Thornwood Bow unlocked!':'Achievement: '+a.name).join(' · '));const target=$('#earned-achievements');if(target)target.innerHTML=unlockCards()+ACHIEVEMENTS.filter(a=>completed.includes(a.id)&&!this.startAchievements.has(a.id)&&!pendingUnlocks().some(n=>n.id===a.id)).map(a=>`<p class="achievement-reward">Completed: ${a.name}${a.reward?' · '+a.reward:''}</p>`).join('');}
