 createHud(){hud.hidden=false;hud.innerHTML=`<div id="zone-name"></div><div id="seal-status"></div><button id="dungeon-action" class="secondary" hidden></button><button id="enter-keep" class="secondary" hidden>Enter the Keep</button><button id="minimap-button" aria-label="Open map"><span id="minimap-label">Exploring</span><canvas id="minimap-canvas" width="320" height="240"></canvas><span class="minimap-hint">Tap to expand · M</span></button><div id="chest-guides" aria-label="Chest locations"></div><div class="xp-track"><div class="xp-fill"></div></div><div class="hud-row"><div class="hud-slots"></div><div class="timer"><span id="time">00:00</span><small>${this.map.name.toUpperCase()}</small></div><div class="hud-right"><span id="player-health" class="player-health"></span><div class="run-counters"><span class="run-coins"><img src="assets/coins.png" alt="Coins"><span id="gold">0</span></span><strong id="level">LV 1</strong></div><div class="run-kills"><span id="kills">0</span> slain</div><div class="hud-buttons"><button id="sound" aria-label="Toggle sound">${soundOn?'♪':'×♪'}</button><button id="pause" aria-label="Pause game">Ⅱ</button></div></div></div><div class="boss-hud" hidden><span></span><div class="boss-track"><div class="boss-fill"></div></div></div><div class="bottom-hint"><span class="desktop-help">WASD to move · Attacks are automatic · Esc to pause</span><span class="mobile-help">Drag to move · Attacks are automatic</span></div>`;$('#dungeon-action').onclick=()=>this.dungeonAction();$('#enter-keep').onclick=()=>this.enterKeep();$('#minimap-button').onclick=()=>this.openMap();$('#pause').onclick=pause;$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound').textContent=soundOn?'♪':'×♪';try{localStorage.setItem('fallen-keep-sound',soundOn?'on':'off');}catch{}if(soundOn)beep();};}
 renderHud(){if(hud.hidden)return;this.renderObjectives();this.renderMinimap();const z=this.map.zones.find(z=>Math.hypot(this.player.x-z.x,this.player.y-z.y)<z.r);$('#zone-name').textContent=z?.name||this.map.name;const gate=this.map.gate,near=gate&&Math.hypot(this.player.x-gate.x,this.player.y-gate.y)<190;$('#enter-keep').hidden=!near;$('#enter-keep').disabled=!this.runHadKey;$('#enter-keep').textContent=this.runHadKey?'Enter the Keep':'Locked · Survive 30 minutes';$('#time').textContent=formatTime(this.elapsed);$('#level').textContent='LV '+this.level;$('#player-health').textContent=Math.ceil(this.hp)+' / '+Math.ceil(this.maxHp())+' HP';$('#kills').textContent=this.kills.toLocaleString();$('#gold').textContent=this.gold.toLocaleString();$('.xp-fill').style.width=clamp(this.xp/xpNeeded(this.level)*100,0,100)+'%';$('.hud-slots').innerHTML=['weapon','passive'].map(kind=>{const list=Object.entries(this.inv).filter(([id])=>ITEMS[id].kind===kind);return '<div class="slot-row" aria-label="'+kind+'s">'+list.map(([id,n])=>`<div class="slot" title="${ITEMS[id].name} ${n}">${art(id)}<b>${ITEMS[id].evolved?'★':n}</b></div>`).join('')+Array.from({length:Math.max(0,6-list.length)},()=>'<div class="slot"></div>').join('')+'</div>';}).join('');const b=this.enemies.find(e=>e.boss&&!e.dead);$('.boss-hud').hidden=!b;if(b){$('.boss-hud span').textContent=b.name;$('.boss-fill').style.width=(b.hp/b.maxHp*100)+'%';}}
 spawnEnemy(type=0,elite=false,boss=false,initial=false,veteran=false){const p=this.player,rect=this.camera.worldView,a=Math.random()*Math.PI*2;const rx=Math.max(rect.width/2,300)+60,ry=Math.max(rect.height/2,230)+60;let x=p.x+Math.cos(a)*rx,y=p.y+Math.sin(a)*ry;if(initial){x=p.x+Math.cos(a)*(240+Math.random()*400);y=p.y+Math.sin(a)*(220+Math.random()*300);}x=clamp(x,160,this.world.w-160);y=clamp(y,210,this.world.h-170);if(Math.hypot(x-p.x,y-p.y)<190){x=clamp(p.x+Math.cos(a)*260,160,this.world.w-160);y=clamp(p.y+Math.sin(a)*260,210,this.world.h-170);}const point=spawnPoint(this.map,p,{x,y});x=point.x;y=point.y;if(this.map.id==='throne'){this.spawnClock=999;this.eliteAt=Infinity;this.bossIndex=3;}const min=this.elapsed/60;const base=[{hp:12,speed:35,damage:8,row:1},{hp:9,speed:62,damage:7,row:2},{hp:27,speed:26,damage:11,row:3}][type];const tier=tierStats(base,min,boss?'boss':elite?'elite':veteran?'veteran':'normal'),hp=tier.hp*this.map.difficulty;const s=this.enemyPool.pop()||this.add.sprite(x,y,'characters','cell'+base.row*4);s.setTexture('characters','cell'+base.row*4).setActive(true).setVisible(true).setPosition(x,y).clearTint().setAlpha(1).setOrigin(.5,base.row===2?.85:base.row===3?.86:.93).setDisplaySize(tier.size,tier.size);s.play('walk'+base.row);if(tier.tint)s.setTint(tier.tint);const e={s,type,hp,maxHp:hp,speed:tier.speed,damage:tier.damage,r:tier.radius,tint:tier.tint,slowCap:tier.slowCap,knockFactor:tier.knockFactor,dropsChest:tier.dropsChest,elite,boss,veteran,dead:false,slow:0,flash:0,hit:0,cast:3+Math.random()*4,name:boss?(this.map.id==='basement'?['The Gaoler','The Bone Steward','The Vault Warden'][this.bossIndex-1]:BOSS_NAMES[this.bossIndex-1]):elite?ELITE_NAMES[type]:'',xp:tier.xp};this.enemies.push(e);return e;}
